// models/Product.js
// The core collection of the whole system.
// `status` is NOT set manually by the user - it is automatically calculated
// from `quantity` vs `lowStockThreshold` every time the product is saved.
//
// PHASE 6: `sku` and `barcode` are auto-generated by the backend (see the
// static helpers below + productController.js's createProduct) rather than
// typed in by the user, per the spec: "Every product should automatically
// receive: unique SKU, unique barcode." `image` is optional and populated
// later via POST /products/:id/image (same pattern as the user profile
// photo upload), since a brand-new product doesn't have an id/file yet.

const mongoose = require('mongoose');
const {
  MAX_PRICE,
  MIN_PRICE,
  MAX_QUANTITY,
  MAX_PRICE_MESSAGE,
  QUANTITY_MESSAGE,
} = require('../utils/productLimits');

const productSchema = new mongoose.Schema(
  {
    name: {
      type: String,
      required: [true, 'Product name is required'],
      trim: true,
    },
    sku: {
      type: String,
      required: [true, 'SKU is required'],
      unique: true,
      trim: true,
      uppercase: true,
    },
    // PHASE 6: unique product barcode, auto-generated on creation.
    // `sparse: true` means multiple documents can have no barcode (e.g.
    // any pre-Phase-6 data) without violating the unique index - only
    // documents that DO have a barcode value need to be distinct.
    barcode: {
      type: String,
      unique: true,
      sparse: true,
      trim: true,
    },
    // PHASE 6: relative URL path to an uploaded product photo, e.g.
    // "/uploads/product-photos/abc123.jpg". Empty string until a photo is
    // uploaded - the frontend shows a placeholder icon in that case.
    image: {
      type: String,
      default: '',
    },
    category: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Category',
      required: [true, 'Category is required'],
    },
    // LIMITS: quantity is an integer 0..1000. Mongoose only validates paths
    // that were modified, so a legacy product that is ALREADY above 1000 is
    // not blocked when something unrelated saves it - but its quantity may
    // only stay the same or go DOWN (e.g. a sale), never up.
    quantity: {
      type: Number,
      required: true,
      min: [0, QUANTITY_MESSAGE],
      default: 0,
      validate: [
        {
          validator: Number.isInteger,
          message: QUANTITY_MESSAGE,
        },
        {
          validator: function (value) {
            if (value <= MAX_QUANTITY) return true;
            const original = this.$locals?.originalQuantity;
            return !this.isNew && typeof original === 'number' && original > MAX_QUANTITY && value <= original;
          },
          message: QUANTITY_MESSAGE,
        },
      ],
    },
    // LIMITS: price is the MRP including GST, 0.01 .. 1,00,00,000, max 2 decimals.
    price: {
      type: Number,
      required: [true, 'Price is required'],
      min: [MIN_PRICE, 'Price must be greater than zero'],
      max: [MAX_PRICE, MAX_PRICE_MESSAGE],
      validate: {
        validator: (value) => Number.isFinite(value) && Number(value.toFixed(2)) === value,
        message: 'Price must have at most 2 decimal places.',
      },
    },
    supplier: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Supplier',
      required: [true, 'Supplier is required'],
    },
    lowStockThreshold: {
      type: Number,
      required: true,
      min: [0, 'Threshold cannot be negative'],
      default: 10,
    },
    // GST rates in percent, stored per product. `price` above is the MRP
    // INCLUDING GST: when this product is sold the customer pays exactly that
    // price, and the GST inside it is worked out from these rates (e.g. MRP
    // 85,000 with SGST 9 + CGST 9 -> taxable 72,033.90, SGST 6,483.05, CGST
    // 6,483.05). Default 0 = no GST, so existing products bill exactly as
    // before until a rate is set on them. See utils/gst.js for the maths.
    sgstRate: {
      type: Number,
      min: [0, 'SGST rate cannot be negative'],
      max: [100, 'SGST rate cannot exceed 100'],
      default: 0,
    },
    cgstRate: {
      type: Number,
      min: [0, 'CGST rate cannot be negative'],
      max: [100, 'CGST rate cannot exceed 100'],
      default: 0,
    },
    igstRate: {
      type: Number,
      min: [0, 'IGST rate cannot be negative'],
      max: [100, 'IGST rate cannot exceed 100'],
      default: 0,
    },
    // Automatically derived - see pre('save') hook below.
    status: {
      type: String,
      enum: ['In Stock', 'Low Stock', 'Out of Stock'],
      default: 'In Stock',
    },
  },
  { timestamps: true }
);

// PHASE 6: builds a human-readable SKU like "ELEC-MOB-0001" from the
// category name + product name, e.g. category "Electronics" + name
// "Mobile Phone" -> prefix "ELEC", midfix "MOB". `sequence` is whatever
// number the caller supplies (productController.js works out the next
// free one) - this function only formats it, it doesn't touch the DB.
productSchema.statics.buildSkuCandidate = function (categoryName, productName, sequence) {
  const clean = (str, maxLen) =>
    (str || '')
      .toUpperCase()
      .replace(/[^A-Z0-9]/g, '')
      .padEnd(maxLen, 'X')
      .slice(0, maxLen);
  const categoryPrefix = clean(categoryName, 4) || 'GEN';
  const namePrefix = clean(productName, 3) || 'PRD';
  const paddedSequence = String(sequence).padStart(4, '0');
  return `${categoryPrefix}-${namePrefix}-${paddedSequence}`;
};

// PHASE 6: builds a purely numeric barcode candidate. Not a "real"
// EAN/UPC checksum-verified barcode - just a unique-looking numeric
// string, which is all this project needs for search/scanning purposes.
productSchema.statics.buildBarcodeCandidate = function () {
  const timestampPart = Date.now().toString().slice(-10); // last 10 digits of the current ms timestamp
  const randomPart = Math.floor(100 + Math.random() * 900); // 3 random digits
  return `${timestampPart}${randomPart}`;
};

// Remember the stock level the document was loaded with (used by the
// quantity validator above to let legacy over-limit products only go down).
productSchema.post('init', function (doc) {
  doc.$locals.originalQuantity = doc.quantity;
});

// Shared logic so both the pre-save hook AND stock update endpoints
// (Phase 4) can recalculate status consistently.
productSchema.methods.calculateStatus = function () {
  if (this.quantity <= 0) return 'Out of Stock';
  if (this.quantity <= this.lowStockThreshold) return 'Low Stock';
  return 'In Stock';
};

// Runs before every save - keeps `status` always in sync with quantity.
//
// BUGFIX: this used to be `function (next) { ...; next(); }` - the
// old-style Mongoose callback pattern. This project's Mongoose version
// (9.x) no longer reliably calls that callback for a plain sync
// function, so `next` could end up `undefined` and calling `next()`
// threw "TypeError: next is not a function" on every single
// product create/update (any .save() call runs this hook). The modern,
// correct pattern for a synchronous pre-hook is just a plain function
// that does its work and returns - no callback parameter, nothing to
// call - Mongoose considers the hook "done" as soon as it returns.
productSchema.pre('save', function () {
  this.status = this.calculateStatus();
});

// PHASE 7: Runs AFTER every save - keeps the StockAlert collection in sync
// with the product's status. This is the single place alert creation
// happens, so it doesn't matter whether the stock changed via creating a
// product, editing it, or the increase/decrease-stock endpoints - the
// alert logic is always applied consistently.
//
// - If the product is now Low Stock or Out of Stock, make sure there's an
//   active alert for it (create one if missing, otherwise refresh its
//   message so the quantity mentioned stays current).
// - If the product is back to In Stock, auto-resolve any active alerts.
//
// PHASE 3: also creates a Notification (for the bell icon), but ONLY when
// a NEW alert is created - not on every message refresh - so Admins/
// Managers don't get spammed with a fresh notification on every single
// stock adjustment while a product stays low.
productSchema.post('save', async function (doc) {
  try {
    // Required here (not at the top of the file) to avoid a circular
    // require between Product.js and StockAlert.js/Notification.js.
    const StockAlert = require('./StockAlert');
    const createNotification = require('../utils/createNotification');

    if (doc.status === 'Low Stock' || doc.status === 'Out of Stock') {
      const message = `"${doc.name}" is ${doc.status} (quantity: ${doc.quantity}, threshold: ${doc.lowStockThreshold})`;
      const existingActive = await StockAlert.findOne({ product: doc._id, status: 'active' });

      if (existingActive) {
        existingActive.message = message; // keep the quantity mentioned up to date
        await existingActive.save();
      } else {
        await StockAlert.create({ product: doc._id, message, status: 'active' });
        // Notify Admin + Manager (who both have inventory oversight per
        // the permission map) - a genuinely NEW low-stock situation.
        const notifType = doc.status === 'Out of Stock' ? 'out_of_stock' : 'low_stock';
        await createNotification('admin', notifType, message, '/alerts');
        await createNotification('manager', notifType, message, '/alerts');
      }
    } else {
      // Status is 'In Stock' - resolve any alerts that were open for this product
      await StockAlert.updateMany(
        { product: doc._id, status: 'active' },
        { status: 'resolved' }
      );
    }
  } catch (error) {
    // Never let alert-syncing break the actual product save.
    console.error('Failed to sync stock alert:', error.message);
  }
});

module.exports = mongoose.model('Product', productSchema);
